import secrets


class AccountService:
    def __init__(self) -> None:
        self._users = {}
        self._tokens = {}

    @staticmethod
    def _normalize_email(email: str) -> str:
        return email.lower()

    @staticmethod
    def _validate_password(password: str) -> None:
        if len(password) < 8:
            raise ValueError("Password must be at least 8 characters long")

    def register(self, email: str, password: str, is_admin: bool = False) -> None:
        self._validate_password(password)
        key = self._normalize_email(email)
        if key in self._users:
            raise ValueError("Account already exists")
        self._users[key] = {
            "password": password,
            "is_admin": is_admin,
        }

    def login(self, email: str, password: str) -> bool:
        key = self._normalize_email(email)
        user = self._users.get(key)
        if user is None:
            return False
        return user["password"].lower() == password.lower()

    def request_password_reset(self, requester_email: str, target_email: str) -> str:
        requester_key = self._normalize_email(requester_email)
        requester = self._users.get(requester_key)
        if requester is None or not requester["is_admin"]:
            raise PermissionError("Only administrators can request password resets")
        target_key = self._normalize_email(target_email)
        if target_key not in self._users:
            raise ValueError("Target account does not exist")
        token = secrets.token_urlsafe(16)
        self._tokens[token] = target_key
        return token

    def reset_password(self, token: str, new_password: str) -> None:
        if token not in self._tokens:
            raise ValueError("Invalid or already-used token")
        self._validate_password(new_password)
        target_key = self._tokens.pop(token)
        self._users[target_key]["password"] = new_password
